// ===== MODUŁ SZKOLENIA =====
// Dwa typy dokumentów, zgodnie ze wzorami zakładowymi:
//  1) KARTA SZKOLENIA STANOWISKOWEGO (indywidualna) — układ dwukolumnowy PL | drugi język
//  2) PROTOKÓŁ SZKOLENIA (grupowy) — osobna strona na każdy język + lista obecności

const szkState = {
  lista: [],
  editingId: null,
  typ: 'indywidualne', // 'indywidualne' | 'grupowe'
  slownik: [],         // baza tłumaczeń: [{ pl, ua, en, es }]
  // Dane nagłówka wydruku (nazwa dokumentu, Nr dokumentu, Opracował, itd.) —
  // WSZYSTKO edytowalne przez użytkownika w "Dane dokumentów", żeby nic nie
  // było zaszyte na sztywno w kodzie. Osobny zestaw dla każdego typu dokumentu.
  dokMetaProtokol: null,
  dokMetaKarta: null,
  // Logo w nagłówku — też edytowalne (wgrywane jako plik), z wbudowanym
  // domyślnym logo jako fallback jeśli user nigdy nic nie wgrał.
  logoDataUri: null
};

// Wartości domyślne — protokół odpowiada temu, co było dotąd zaszyte na sztywno
// (żeby nic się nie zmieniło, dopóki użytkownik sam nie zmieni); karta zaczyna
// z rozsądną domyślną nazwą, resztę pól pustą (nie znaliśmy prawdziwych danych).
const SZK_DOK_META_DOMYSLNE_PROTOKOL = {
  nazwa: 'Protokół szkolenia',
  nrDok: 'P11/K01', opracowal: 'Katarzyna Raatz',
  nrWydania: '1', dataWydania: '05.04.2022', zatwierdzil: 'Tomasz Gajkowski',
  symbol: 'P11', symbolOpis: 'Pracownicy i goście'
};
const SZK_DOK_META_DOMYSLNE_KARTA = {
  nazwa: 'Karta szkolenia stanowiskowego',
  nrDok: '', opracowal: '', nrWydania: '', dataWydania: '', zatwierdzil: '',
  symbol: '', symbolOpis: ''
};

async function szkLoadDokMeta() {
  const p = await DB.getSetting('szkDokMetaProtokol', null);
  const k = await DB.getSetting('szkDokMetaKarta', null);
  szkState.dokMetaProtokol = Object.assign({}, SZK_DOK_META_DOMYSLNE_PROTOKOL, p || {});
  szkState.dokMetaKarta = Object.assign({}, SZK_DOK_META_DOMYSLNE_KARTA, k || {});
  const logo = await DB.getSetting('szkLogoCustom', null);
  szkState.logoDataUri = logo || SZK_LOGO_DEFAULT;
}

// ===== SŁOWNIK TŁUMACZEŃ (baza rosnąca w miarę używania) =====
// Każda pozycja to jedna fraza po polsku wraz z tłumaczeniami.
// Zapełnia się na dwa sposoby: automatycznie przy zapisie karty oraz ręcznie.

async function szkLoadSlownik() {
  const saved = await DB.getSetting('szkolenieSlownik', null);
  szkState.slownik = Array.isArray(saved) ? saved : [];
  return szkState.slownik;
}

async function szkSaveSlownik() {
  await DB.setSetting('szkolenieSlownik', szkState.slownik);
}

// Klucz porównawczy — bez wielkości liter, znaczników i nadmiarowych spacji
function szkKluczFrazy(txt) {
  return szkUsunZnaczniki(String(txt || ''))
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

// Szuka tłumaczenia danej frazy w wybranym języku
function szkZnajdzTlumaczenie(plTekst, lang) {
  const klucz = szkKluczFrazy(plTekst);
  if (!klucz) return '';
  const poz = szkState.slownik.find(p => szkKluczFrazy(p.pl) === klucz);
  return poz ? (poz[lang] || '') : '';
}

// Dopisuje/aktualizuje pozycję. Nie nadpisuje istniejącego tłumaczenia pustym.
function szkDopiszDoSlownika(plTekst, lang, tlumaczenie) {
  const czystyPl = szkUsunZnaczniki(String(plTekst || '')).trim();
  const czysteTlum = szkUsunZnaczniki(String(tlumaczenie || '')).trim();
  if (!czystyPl || !czysteTlum) return false;
  // Fraza w całości oznaczona gwiazdkami nie podlega tłumaczeniu — nie zapisujemy
  if (szkCalaLiniaBezTlumaczenia(plTekst)) return false;

  const klucz = szkKluczFrazy(czystyPl);
  const istniejaca = szkState.slownik.find(p => szkKluczFrazy(p.pl) === klucz);
  if (istniejaca) {
    if (istniejaca[lang] === czysteTlum) return false;
    istniejaca[lang] = czysteTlum;
    return true;
  }
  const nowa = { pl: czystyPl, ua: '', en: '', es: '' };
  nowa[lang] = czysteTlum;
  szkState.slownik.push(nowa);
  return true;
}

// Po zapisie karty — zbiera pary z pól listowych i nagłówka
async function szkZapiszParyDoSlownika(rec) {
  const lang = rec.jezykDodatkowy || 'ua';
  let zmian = 0;

  const pary = [];
  if (rec.typ === 'indywidualne') {
    pary.push([rec.obszarPl, rec.obszarTlum]);
    pary.push([rec.stanowisko, rec.stanowiskoTlum]);
    const aPl = szkLiniaDoWierszy(rec.agendaPl), aTl = szkLiniaDoWierszy(rec.agendaTlum);
    for (let i = 0; i < Math.min(aPl.length, aTl.length); i++) pary.push([aPl[i], aTl[i]]);
    // Sekcja II — nowy format (obszary) albo stary (płaska matryca)
    if (Array.isArray(rec.obszaryMatrycy) && rec.obszaryMatrycy.length) {
      for (const o of rec.obszaryMatrycy) {
        const oPl = szkLiniaDoWierszy(o.pozycjePl), oTl = szkLiniaDoWierszy(o.pozycjeTlum);
        for (let i = 0; i < Math.min(oPl.length, oTl.length); i++) pary.push([oPl[i], oTl[i]]);
      }
    } else {
      const mPl = szkLiniaDoWierszy(rec.matrycaPl), mTl = szkLiniaDoWierszy(rec.matrycaTlum);
      for (let i = 0; i < Math.min(mPl.length, mTl.length); i++) pary.push([mPl[i], mTl[i]]);
    }
  } else {
    pary.push([rec.temat, rec.tematTlum]);
    const pPl = szkLiniaDoWierszy(rec.programPl), pTl = szkLiniaDoWierszy(rec.programTlum);
    for (let i = 0; i < Math.min(pPl.length, pTl.length); i++) pary.push([pPl[i], pTl[i]]);
  }

  for (const [pl, tl] of pary) {
    if (szkDopiszDoSlownika(pl, lang, tl)) zmian++;
  }
  if (zmian) await szkSaveSlownik();
  return zmian;
}

// Uzupełnia brakujące tłumaczenia w polu listowym na podstawie słownika.
// Zwraca { tekst, uzupelnione, brakujace }
function szkUzupelnijListe(plTekst, tlumTekst, lang) {
  const plLinie = szkLiniaDoWierszy(plTekst);
  const tlLinie = szkLiniaDoWierszy(tlumTekst);
  const wynik = [];
  let uzupelnione = 0, brakujace = 0;

  for (let i = 0; i < plLinie.length; i++) {
    const istniejace = (tlLinie[i] || '').trim();
    if (istniejace) { wynik.push(istniejace); continue; }
    // Pozycja oznaczona gwiazdkami — zostaje bez tłumaczenia
    if (szkCalaLiniaBezTlumaczenia(plLinie[i])) { wynik.push(''); continue; }
    const znalezione = szkZnajdzTlumaczenie(plLinie[i], lang);
    if (znalezione) { wynik.push(znalezione); uzupelnione++; }
    else { wynik.push(''); brakujace++; }
  }
  return { tekst: wynik.join('\n'), uzupelnione, brakujace };
}


