function szkT(lang, key) {
  const dict = SZK_I18N[lang] || SZK_I18N.pl;
  return dict[key] || SZK_I18N.pl[key] || key;
}

// ===== WYSZUKIWANIE I WYBÓR PRACOWNIKA Z LISTY (karty szkoleniowe) =====
// Ten sam wzorzec "wpisz, żeby zawęzić, kliknij, żeby wybrać" co przy wyborze
// towaru w Magazynie — przeszukuje WSZYSTKICH aktywnych pracowników z systemu
// (obsState.employees, ładowane przez moduł Obecność). Pole zostaje zwykłym
// tekstem, więc dalej można wpisać ręcznie kogoś spoza systemu (gościa).
function renderEmployeeSuggestions(query, containerId, onPick) {
  const container = document.getElementById(containerId);
  if (!container) return;
  const q = (query || '').trim().toLowerCase();
  if (!q) { container.innerHTML = ''; container.style.display = 'none'; return; }

  const employees = (typeof obsState !== 'undefined' && obsState.employees) ? obsState.employees : [];
  const matches = employees.filter(e =>
    e.active !== 0 && (
      `${e.firstName || ''} ${e.lastName || ''}`.toLowerCase().includes(q) ||
      `${e.lastName || ''} ${e.firstName || ''}`.toLowerCase().includes(q)
    )
  ).slice(0, 8);

  if (!matches.length) {
    container.innerHTML = `<div class="search-suggestion-empty">Brak pracownika o takim imieniu/nazwisku w systemie — możesz wpisać je ręcznie.</div>`;
  } else {
    container.innerHTML = matches.map(e =>
      `<div class="search-suggestion-item" data-id="${e.id}">${escapeHtml(`${e.firstName || ''} ${e.lastName || ''}`.trim())}</div>`
    ).join('');
  }
  container.style.display = 'block';
  container.querySelectorAll('.search-suggestion-item[data-id]').forEach(el => {
    el.addEventListener('click', () => {
      const emp = employees.find(e => e.id === el.dataset.id);
      container.innerHTML = '';
      container.style.display = 'none';
      if (emp) onPick(emp);
    });
  });
}

// ===== INICJALIZACJA =====
async function initSzkolenia() {
  szkState.lista = await DB.getSzkolenia();
  await szkLoadSlownik();
  await szkLoadDokMeta();
  renderSzkoleniaList();
}

function szkEsc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function szkFormatDate(d) {
  if (!d) return '';
  const parts = String(d).split('-');
  if (parts.length === 3) return `${parts[2]}.${parts[1]}.${parts[0]}`;
  return d;
}

// ===== LISTA SZKOLEŃ =====
function renderSzkoleniaList() {
  const wrap = document.getElementById('szkoleniaList');
  if (!wrap) return;
  const lista = (szkState.lista || []).slice().sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));

  const indyw = lista.filter(s => s.typ === 'indywidualne');
  const grup = lista.filter(s => s.typ === 'grupowe');

  const rowHtml = (s) => {
    const tytul = s.typ === 'indywidualne'
      ? `${szkEsc(s.pracownikImieNazwisko || '(bez nazwiska)')}`
      : `${szkEsc(s.temat || '(bez tematu)')}`;
    const pod = s.typ === 'indywidualne'
      ? `${szkEsc(s.stanowisko || '')} · ${szkFormatDate(s.dataOd)} – ${szkFormatDate(s.dataDo)}`
      : `${szkFormatDate(s.data)} · ${szkEsc(s.uczestnicy ? s.uczestnicy.length : 0)} uczestników`;
    const jez = (s.jezykDodatkowy || 'ua').toUpperCase();
    return `
      <div class="storage-row" style="margin-bottom:6px;">
        <span><strong>${tytul}</strong>
          <span style="font-size:11px;font-weight:700;color:var(--accent2);border:1px solid var(--accent2);border-radius:4px;padding:1px 6px;margin-left:4px;">PL–${szkEsc(jez)}</span>
          <br><span style="font-size:12px;color:var(--text-dim);">${pod}</span>
        </span>
        <span>
          <button class="btn secondary" data-szk-edit="${s.id}" style="margin-right:4px;">Edytuj</button>
          <button class="btn" data-szk-print="${s.id}" style="margin-right:4px;">🖨️ Drukuj</button>
          <button class="btn danger" data-szk-del="${s.id}">Usuń</button>
        </span>
      </div>`;
  };

  wrap.innerHTML = `
    <div style="font-size:12px;font-weight:800;color:var(--accent2);text-transform:uppercase;letter-spacing:.5px;margin:4px 0 8px;">👤 Szkolenia indywidualne (${indyw.length})</div>
    ${indyw.length ? indyw.map(rowHtml).join('') : '<div class="hint" style="margin-bottom:10px;">— brak —</div>'}
    <div style="font-size:12px;font-weight:800;color:var(--accent);text-transform:uppercase;letter-spacing:.5px;margin:14px 0 8px;">👥 Szkolenia grupowe (${grup.length})</div>
    ${grup.length ? grup.map(rowHtml).join('') : '<div class="hint">— brak —</div>'}
  `;

  wrap.querySelectorAll('[data-szk-edit]').forEach(btn => {
    btn.addEventListener('click', () => openSzkolenieModal(btn.dataset.szkEdit));
  });
  wrap.querySelectorAll('[data-szk-print]').forEach(btn => {
    btn.addEventListener('click', () => drukujSzkolenie(btn.dataset.szkPrint));
  });
  wrap.querySelectorAll('[data-szk-del]').forEach(btn => {
    btn.addEventListener('click', async () => {
      if (!confirm('Usunąć tę kartę szkolenia? Tej operacji nie można cofnąć.')) return;
      await DB.deleteSzkolenie(btn.dataset.szkDel);
      szkState.lista = szkState.lista.filter(s => s.id !== btn.dataset.szkDel);
      renderSzkoleniaList();
      showToast('Karta szkolenia usunięta');
    });
  });
}

// ===== FORMULARZ =====
function openSzkolenieModal(id) {
  const isNew = !id;
  szkState.editingId = id || null;
  const s = isNew ? null : szkState.lista.find(x => x.id === id);
  const typ = s ? s.typ : szkState.typ;

  document.getElementById('szkModalTitle').textContent = isNew
    ? (typ === 'indywidualne' ? 'Nowa karta szkolenia stanowiskowego' : 'Nowy protokół szkolenia grupowego')
    : 'Edycja karty szkolenia';

  document.getElementById('szkFormIndywidualne').style.display = typ === 'indywidualne' ? 'block' : 'none';
  document.getElementById('szkFormGrupowe').style.display = typ === 'grupowe' ? 'block' : 'none';

  const jezSel = document.getElementById('szkJezykDodatkowy');
  jezSel.value = s ? (s.jezykDodatkowy || 'ua') : 'ua';

  if (typ === 'indywidualne') {
    document.getElementById('szkPracownik').value = s ? (s.pracownikImieNazwisko || '') : '';
    document.getElementById('szkDataOd').value = s ? (s.dataOd || '') : todayStr();
    document.getElementById('szkDataDo').value = s ? (s.dataDo || '') : '';
    document.getElementById('szkObszar').value = s ? (s.obszarPl || '') : '';
    document.getElementById('szkObszarTlum').value = s ? (s.obszarTlum || '') : '';
    document.getElementById('szkStanowisko').value = s ? (s.stanowisko || '') : '';
    document.getElementById('szkStanowiskoTlum').value = s ? (s.stanowiskoTlum || '') : '';
    document.getElementById('szkPrzelozony').value = s ? (s.przelozony || '') : '';
    document.getElementById('szkTrener').value = s ? (s.trener || '') : '';
    document.getElementById('szkTrybPelny').checked = s ? (s.trybPelny !== false) : true;
    document.getElementById('szkAgendaPl').value = s ? (s.agendaPl || '') : '';
    document.getElementById('szkAgendaTlum').value = s ? (s.agendaTlum || '') : '';
    // Sekcja II — obszary. Karty zapisane przed tą zmianą mają płaską matrycę:
    // wczytujemy ją jako jeden obszar bez nazwy, żeby dało się ją dalej edytować.
    if (s && Array.isArray(s.obszaryMatrycy) && s.obszaryMatrycy.length) {
      szkObszaryRobocze = s.obszaryMatrycy.map(o => szkNowyObszar(o.nazwa, o.pozycjePl, o.pozycjeTlum));
    } else if (s && (s.matrycaPl || '').trim()) {
      szkObszaryRobocze = [szkNowyObszar('', s.matrycaPl, s.matrycaTlum)];
    } else {
      szkObszaryRobocze = [];
    }
    renderSzkObszary();
  } else {
    document.getElementById('szkTemat').value = s ? (s.temat || '') : '';
    document.getElementById('szkTematTlum').value = s ? (s.tematTlum || '') : '';
    document.getElementById('szkMiejsce').value = s ? (s.miejsce || '') : '';
    document.getElementById('szkFirma').value = s ? (s.firma || 'PERLA') : 'PERLA';
    document.getElementById('szkData').value = s ? (s.data || '') : todayStr();
    document.getElementById('szkCzasTrwania').value = s ? (s.czasTrwania || '') : '';
    document.getElementById('szkOsobaSzkolaca').value = s ? (s.osobaSzkolaca || '') : '';
    document.getElementById('szkTlumacz').value = s ? (s.tlumacz || '') : '';
    document.getElementById('szkProgramPl').value = s ? (s.programPl || '') : '';
    document.getElementById('szkProgramTlum').value = s ? (s.programTlum || '') : '';
    document.getElementById('szkUwagi').value = s ? (s.uwagi || '') : '';
    document.getElementById('szkUczestnicy').value = s && s.uczestnicy ? s.uczestnicy.join('\n') : '';
  }

  const uczSearch = document.getElementById('szkUczestnicySearch');
  if (uczSearch) uczSearch.value = '';
  const uczSug = document.getElementById('szkUczestnicySuggestions');
  if (uczSug) { uczSug.innerHTML = ''; uczSug.style.display = 'none'; }

  document.getElementById('szkModalOverlay').classList.add('active');
}

document.getElementById('newSzkIndywBtn') && document.getElementById('newSzkIndywBtn').addEventListener('click', () => {
  szkState.typ = 'indywidualne';
  openSzkolenieModal(null);
});
document.getElementById('newSzkGrupBtn') && document.getElementById('newSzkGrupBtn').addEventListener('click', () => {
  szkState.typ = 'grupowe';
  openSzkolenieModal(null);
});
document.getElementById('closeSzkModal') && document.getElementById('closeSzkModal').addEventListener('click', () => {
  document.getElementById('szkModalOverlay').classList.remove('active');
});
// Kliknięcie poza oknem NIE zamyka go (aby nie tracić wpisanych danych) — zamykanie tylko przez przycisk X / Anuluj. (szkModalOverlay)

document.getElementById('saveSzkBtn') && document.getElementById('saveSzkBtn').addEventListener('click', async () => {
  const editing = szkState.editingId ? szkState.lista.find(x => x.id === szkState.editingId) : null;
  const typ = editing ? editing.typ : szkState.typ;
  const jezykDodatkowy = document.getElementById('szkJezykDodatkowy').value;

  let rec;
  if (typ === 'indywidualne') {
    const pracownik = document.getElementById('szkPracownik').value.trim();
    if (!pracownik) { showToast('Podaj imię i nazwisko pracownika'); return; }
    rec = {
      id: szkState.editingId || undefined,
      typ: 'indywidualne',
      jezykDodatkowy,
      pracownikImieNazwisko: pracownik,
      dataOd: document.getElementById('szkDataOd').value,
      dataDo: document.getElementById('szkDataDo').value,
      obszarPl: document.getElementById('szkObszar').value.trim(),
      obszarTlum: document.getElementById('szkObszarTlum').value.trim(),
      stanowisko: document.getElementById('szkStanowisko').value.trim(),
      stanowiskoTlum: document.getElementById('szkStanowiskoTlum').value.trim(),
      przelozony: document.getElementById('szkPrzelozony').value.trim(),
      trener: document.getElementById('szkTrener').value.trim(),
      trybPelny: document.getElementById('szkTrybPelny').checked,
      agendaPl: document.getElementById('szkAgendaPl').value,
      agendaTlum: document.getElementById('szkAgendaTlum').value,
      obszaryMatrycy: szkObszaryRobocze
        .filter(o => (o.nazwa || '').trim() || (o.pozycjePl || '').trim())
        .map(o => ({
          nazwa: (o.nazwa || '').trim(),
          pozycjePl: o.pozycjePl || '',
          pozycjeTlum: o.pozycjeTlum || ''
        }))
    };
  } else {
    const temat = document.getElementById('szkTemat').value.trim();
    if (!temat) { showToast('Podaj temat szkolenia'); return; }
    rec = {
      id: szkState.editingId || undefined,
      typ: 'grupowe',
      jezykDodatkowy,
      temat,
      tematTlum: document.getElementById('szkTematTlum').value.trim(),
      miejsce: document.getElementById('szkMiejsce').value.trim(),
      firma: document.getElementById('szkFirma').value.trim(),
      data: document.getElementById('szkData').value,
      czasTrwania: document.getElementById('szkCzasTrwania').value.trim(),
      osobaSzkolaca: document.getElementById('szkOsobaSzkolaca').value.trim(),
      tlumacz: document.getElementById('szkTlumacz').value.trim(),
      programPl: document.getElementById('szkProgramPl').value,
      programTlum: document.getElementById('szkProgramTlum').value,
      uwagi: document.getElementById('szkUwagi').value,
      uczestnicy: document.getElementById('szkUczestnicy').value.split('\n').map(x => x.trim()).filter(Boolean)
    };
  }
  if (editing) { rec.createdAt = editing.createdAt; rec.id = editing.id; }

  await DB.saveSzkolenie(rec);
  // Słownik rośnie sam — każda para (polski + tłumaczenie) trafia do bazy
  const dodane = await szkZapiszParyDoSlownika(rec);
  szkState.lista = await DB.getSzkolenia();
  renderSzkoleniaList();
  const wasEditing = !!szkState.editingId;
  const komunikat = wasEditing ? 'Karta zaktualizowana' : 'Karta szkolenia zapisana — możesz dodać kolejną';
  showToast(dodane ? `${komunikat} · słownik: +${dodane}` : komunikat);
  if (wasEditing) {
    document.getElementById('szkModalOverlay').classList.remove('active');
    szkState.editingId = null;
  } else {
    openSzkolenieModal(null); // zostaw okno otwarte, gotowe na kolejną kartę tego samego typu
  }
});

