function szkLiniaDoWierszy(txt) {
  return String(txt || '').split('\n').map(l => l.trim()).filter(Boolean);
}

// ===== TEKST NIEPODLEGAJĄCY TŁUMACZENIU =====
// Gwiazdka to wewnętrzny znacznik: *tekst* zostaje po polsku (nazwy techniczne
// maszyn, pomieszczeń, urządzeń). Same gwiazdki nie pojawiają się na wydruku.
//
// Działa na dwa sposoby:
//   1) Cała linia w gwiazdkach — *Obsługa szorowarki* → pozycja bez tłumaczenia
//   2) Fragment w środku zdania — Czyszczenie *szorowarki* → tłumaczy się reszta,
//      nazwa zostaje po polsku

// Czy cała treść jest objęta gwiazdkami (po odrzuceniu spacji)?
function szkCalaLiniaBezTlumaczenia(txt) {
  const t = String(txt || '').trim();
  if (t.length < 3) return false;
  if (!t.startsWith('*') || !t.endsWith('*')) return false;
  // Wewnątrz nie może być kolejnej gwiazdki — inaczej to dwa osobne fragmenty
  return t.slice(1, -1).indexOf('*') === -1;
}

// Usuwa znaczniki, zostawia sam tekst
function szkUsunZnaczniki(txt) {
  return String(txt || '').replace(/\*([^*]*)\*/g, '$1');
}

// Czy w treści jest jakikolwiek znacznik?
function szkMaZnaczniki(txt) {
  return /\*[^*]*\*/.test(String(txt || ''));
}

// Składa wiersz: tekst polski + tłumaczenie, z uwzględnieniem znaczników.
// Zwraca { pl, tlum } — gotowe do wstawienia, bez gwiazdek.
function szkZlozWiersz(plRaw, tlumRaw) {
  const pl = szkUsunZnaczniki(plRaw);

  // Cała linia oznaczona — nazwa techniczna, bez tłumaczenia
  if (szkCalaLiniaBezTlumaczenia(plRaw)) {
    return { pl, tlum: '' };
  }

  // Brak tłumaczenia w polu obok — zostaw samą treść polską
  if (!String(tlumRaw || '').trim()) {
    return { pl, tlum: '' };
  }

  return { pl, tlum: szkUsunZnaczniki(tlumRaw) };
}

// Karta indywidualna — układ dwukolumnowy PL | drugi język (jak we wzorze)
function budujKarteIndywidualna(s) {
  const L2 = s.jezykDodatkowy || 'ua';
  const t1 = (k) => szkEsc(szkT('pl', k));
  const t2 = (k) => szkEsc(szkT(L2, k));

  const agendaPl = szkLiniaDoWierszy(s.agendaPl);
  const agendaTl = szkLiniaDoWierszy(s.agendaTlum);
  const maxAgenda = Math.max(agendaPl.length, agendaTl.length);
  let agendaRows = '';
  for (let i = 0; i < maxAgenda; i++) {
    const w = szkZlozWiersz(agendaPl[i] || '', agendaTl[i] || '');
    agendaRows += `<tr><td>${szkEsc(w.pl)}</td><td class="tlum">${szkEsc(w.tlum)}</td></tr>`;
  }
  if (!maxAgenda) agendaRows = '<tr><td class="pusty"></td><td></td></tr>';

  // Sekcja II — nagłówek kolumn wspólny dla wszystkich tabel obszarów
  const naglowekMatrycy = `<thead><tr class="naglowek-tabeli">
        <td>${t1('lp')}<br><span style="font-weight:normal;">${t2('lp')}</span></td>
        <td>${t1('zakres')}<br><span style="font-weight:normal;">${t2('zakres')}</span></td>
        <td>${t1('parafaTrenera')}<br><span style="font-weight:normal;">${t2('parafaTrenera')}</span></td>
        <td>${t1('data')}<br><span style="font-weight:normal;">${t2('data')}</span></td>
        <td>${t1('podpisPracownika')}<br><span style="font-weight:normal;">${t2('podpisPracownika')}</span></td>
        <td>${t1('podpisTrenera')}<br><span style="font-weight:normal;">${t2('podpisTrenera')}</span></td>
      </tr></thead>`;

  // Blok podpisów powtarzany pod każdą tabelą obszaru
  const blokPodpisow = `<div class="podpisy">
      <div class="podpis">${t1('dataPodpisPracownika')}<br><span class="tlum">${t2('dataPodpisPracownika')}</span></div>
      <div class="podpis">${t1('dataPodpisTrenera')}<br><span class="tlum">${t2('dataPodpisTrenera')}</span></div>
      <div class="podpis">${t1('dataPodpisKierownika')}<br><span class="tlum">${t2('dataPodpisKierownika')}</span></div>
    </div>`;

  // Buduje wiersze jednej tabeli z listy pozycji
  const budujWiersze = (plTxt, tlumTxt) => {
    const pl = szkLiniaDoWierszy(plTxt);
    const tl = szkLiniaDoWierszy(tlumTxt);
    const ile = Math.max(pl.length, tl.length, 1);
    let rows = '';
    for (let i = 0; i < ile; i++) {
      const w = szkZlozWiersz(pl[i] || '', tl[i] || '');
      rows += `<tr>
        <td style="text-align:center;width:8%;">${i + 1}</td>
        <td style="width:42%;">${szkEsc(w.pl)}${w.tlum ? '<br><span class="tlum">' + szkEsc(w.tlum) + '</span>' : ''}</td>
        <td style="width:12%;"></td><td style="width:12%;"></td><td style="width:13%;"></td><td style="width:13%;"></td>
      </tr>`;
    }
    return rows;
  };

  // Rubryka "Weryfikacja skuteczności szkolenia" — ta sama pozycja co w protokole
  // grupowym: tuż przed ostatnim blokiem podpisów, jedna na cały dokument
  // (nie powtarzana przy każdym obszarze).
  const weryfikacjaHtml = `
    <table style="margin-top:3mm;">
      <tr><td><span class="lbl">${t1('weryfikacja')}</span><br><span class="tlum">${t2('weryfikacja')}</span></td></tr>
      <tr><td style="height:15mm;"></td></tr>
    </table>
    <div class="podpisy" style="margin-top:2mm;">
      <div class="podpis">${t1('podpisWeryfikujacego')} / ${t2('podpisWeryfikujacego')}<br><span class="tlum">${t1('czytelnie')}</span></div>
    </div>`;

  // Nowy format: osobna tabela + podpisy na obszar. Stary: jedna tabela bez podziału.
  let sekcja2Html = '';
  if (Array.isArray(s.obszaryMatrycy) && s.obszaryMatrycy.length) {
    sekcja2Html = s.obszaryMatrycy.map((o, idx) => {
      const nazwa = szkUsunZnaczniki(o.nazwa || '').trim();
      const ostatni = idx === s.obszaryMatrycy.length - 1;
      return `
    <div class="obszar-blok">
      ${nazwa ? `<div class="obszar-naglowek">${szkEsc(nazwa)}</div>` : ''}
      <table>
        ${naglowekMatrycy}
        <tbody>${budujWiersze(o.pozycjePl, o.pozycjeTlum)}</tbody>
      </table>
      ${ostatni ? weryfikacjaHtml : ''}
      ${blokPodpisow}
    </div>`;
    }).join('');
  } else {
    sekcja2Html = `
    <table>
      ${naglowekMatrycy}
      <tbody>${budujWiersze(s.matrycaPl, s.matrycaTlum)}</tbody>
    </table>
    ${weryfikacjaHtml}
    ${blokPodpisow}`;
  }

  return `
  <div class="doc">
    <div class="naglowek-dok">
      <div style="width:22%;display:flex;align-items:center;justify-content:center;padding:1mm;"><img src="${szkState.logoDataUri}" style="height:24mm;max-width:100%;display:block;" alt="perla"></div>
      <div style="width:38%;">
        <strong>${szkEsc(szkState.dokMetaKarta.nazwa)}</strong><br>
        Nr dok.: ${szkEsc(szkState.dokMetaKarta.nrDok)}<br>
        Opracował: ${szkEsc(szkState.dokMetaKarta.opracowal)}
      </div>
      <div style="width:25%;">Nr wydania: ${szkEsc(szkState.dokMetaKarta.nrWydania)}<br>Data wyd.: ${szkEsc(szkState.dokMetaKarta.dataWydania)}<br>Zatwierdził:<br>${szkEsc(szkState.dokMetaKarta.zatwierdzil)}</div>
      <div style="width:15%;text-align:center;"><strong>${szkEsc(szkState.dokMetaKarta.symbol)}</strong><br>${szkEsc(szkState.dokMetaKarta.symbolOpis)}</div>
    </div>

    <h1>${t1('kartaTytul')}</h1>
    <h2>${t2('kartaTytul')}</h2>

    <table>
      <tr>
        <td colspan="2"><span class="lbl">${t1('imieNazwisko')} / <span class="tlum">${t2('imieNazwisko')}</span></span><br>
          <strong style="font-size:11pt;">${szkEsc(szkUsunZnaczniki(s.pracownikImieNazwisko))}</strong></td>
      </tr>
      <tr>
        <td style="width:50%;"><span class="lbl">${t1('dataRozpoczecia')} / <span class="tlum">${t2('dataRozpoczecia')}</span></span><br>${szkFormatDate(s.dataOd)}</td>
        <td style="width:50%;"><span class="lbl">${t1('dataZakonczenia')} / <span class="tlum">${t2('dataZakonczenia')}</span></span><br>${szkFormatDate(s.dataDo)}</td>
      </tr>
      <tr>
        <td><span class="lbl">${t1('obszar')} / <span class="tlum">${t2('obszar')}</span></span><br>
          ${(() => { const w = szkZlozWiersz(s.obszarPl, s.obszarTlum); return szkEsc(w.pl) + (w.tlum ? ' / <span class="tlum">' + szkEsc(w.tlum) + '</span>' : ''); })()}</td>
        <td><span class="lbl">${t1('stanowisko')} / <span class="tlum">${t2('stanowisko')}</span></span><br>
          ${(() => { const w = szkZlozWiersz(s.stanowisko, s.stanowiskoTlum); return szkEsc(w.pl) + (w.tlum ? ' / <span class="tlum">' + szkEsc(w.tlum) + '</span>' : ''); })()}</td>
      </tr>
      <tr>
        <td><span class="lbl">${t1('przelozony')} / <span class="tlum">${t2('przelozony')}</span></span><br>${szkEsc(szkUsunZnaczniki(s.przelozony))}</td>
        <td><span class="lbl">${t1('osobaOdpowiedzialna')} / <span class="tlum">${t2('osobaOdpowiedzialna')}</span></span><br>${szkEsc(szkUsunZnaczniki(s.trener))}</td>
      </tr>
    </table>

    <div class="sekcja">${t1('wyborTrybu')} / ${t2('wyborTrybu')}</div>
    <div class="tryb">
      <strong>[${s.trybPelny ? 'x' : ' '}] ${t1('opcjaA')}</strong> ${t1('opcjaAOpis')}<br>
      <span class="tlum">[${s.trybPelny ? 'x' : ' '}] ${t2('opcjaA')} ${t2('opcjaAOpis')}</span><br><br>
      <strong>[${s.trybPelny ? ' ' : 'x'}] ${t1('opcjaB')}</strong> ${t1('opcjaBOpis')}<br>
      <span class="tlum">[${s.trybPelny ? ' ' : 'x'}] ${t2('opcjaB')} ${t2('opcjaBOpis')}</span>
    </div>

    <div class="sekcja">${t1('sekcja1')} / ${t2('sekcja1')}</div>
    <table>
      <thead><tr class="naglowek-tabeli"><td style="width:50%;">${t1('krokPoKroku')}</td><td style="width:50%;">${t2('krokPoKroku')}</td></tr></thead>
      <tbody>${agendaRows}</tbody>
    </table>

    <div class="sekcja">${t1('deklaracjaTytul')} / ${t2('deklaracjaTytul')}</div>
    <div class="tryb">
      <div class="deklaracja"><strong>${t1('deklaracjaZastosowanie')}</strong></div>
      <div class="deklaracja tlum">${t2('deklaracjaZastosowanie')}</div>
      <div class="deklaracja">${t1('deklaracjaTresc')}</div>
      <div class="deklaracja tlum">${t2('deklaracjaTresc')}</div>
    </div>

    <div class="sekcja">${t1('sekcja2')} / ${t2('sekcja2')}</div>
    ${sekcja2Html}
  </div>`;
}

// Protokół grupowy — osobna strona na każdy język + lista obecności (jak we wzorze)
function budujProtokolGrupowy(s) {
  const L2 = s.jezykDodatkowy || 'en';
  const strona = (lang, nrStrony, temat, program) => {
    const t = (k) => szkEsc(szkT(lang, k));
    // Znaczniki *…* to wewnętrzny zapis — na wydruku ich nie ma
    const programRows = szkLiniaDoWierszy(program).map(l => `<div style="margin-bottom:1.5mm;">▸ ${szkEsc(szkUsunZnaczniki(l))}</div>`).join('') || '<div class="pusty"></div>';
    return `
    <div class="doc">
      <div class="naglowek-dok">
        <div style="width:22%;display:flex;align-items:center;justify-content:center;padding:1mm;"><img src="${szkState.logoDataUri}" style="height:24mm;max-width:100%;display:block;" alt="perla"></div>
        <div style="width:38%;">
          <strong>${szkEsc(szkState.dokMetaProtokol.nazwa)}</strong><br>
          ${t('stron')}: ${nrStrony}/3<br>
          Nr dok.: ${szkEsc(szkState.dokMetaProtokol.nrDok)}<br>
          Opracował: ${szkEsc(szkState.dokMetaProtokol.opracowal)}
        </div>
        <div style="width:25%;">Nr wydania: ${szkEsc(szkState.dokMetaProtokol.nrWydania)}<br>Data wyd.: ${szkEsc(szkState.dokMetaProtokol.dataWydania)}<br>Zatwierdził:<br>${szkEsc(szkState.dokMetaProtokol.zatwierdzil)}</div>
        <div style="width:15%;text-align:center;"><strong>${szkEsc(szkState.dokMetaProtokol.symbol)}</strong><br>${szkEsc(szkState.dokMetaProtokol.symbolOpis)}</div>
      </div>

      <table>
        <tr><td style="width:25%;"><span class="lbl">${t('tematSzkolenia')}</span></td>
            <td colspan="3"><strong>${szkEsc(szkUsunZnaczniki(temat))}</strong></td></tr>
        <tr><td><span class="lbl">${t('miejsceSzkolenia')}</span></td>
            <td style="width:30%;">${szkEsc(szkUsunZnaczniki(s.miejsce))}</td>
            <td style="width:25%;"><span class="lbl">${t('nazwaFirmy')}: ${szkEsc(szkUsunZnaczniki(s.firma))}</span></td>
            <td style="width:20%;"><strong>${t('rodzajSzkolenia')}</strong></td></tr>
        <tr><td><span class="lbl">${t('data')}</span></td>
            <td>${szkFormatDate(s.data)}</td>
            <td><span class="lbl">${t('czasTrwania')}</span></td>
            <td>${szkEsc(szkUsunZnaczniki(s.czasTrwania))}</td></tr>
        <tr><td><span class="lbl">${t('osobaSzkolaca')}</span><br><span class="tlum" style="font-size:7pt;">${t('imieNazwiskoMale')}</span></td>
            <td>${szkEsc(szkUsunZnaczniki(s.osobaSzkolaca))}</td>
            <td><span class="lbl">${t('tlumacz')}</span><br><span class="tlum" style="font-size:7pt;">${t('imieNazwiskoMale')}</span></td>
            <td>${szkEsc(szkUsunZnaczniki(s.tlumacz))}</td></tr>
        <tr><td><span class="lbl">${t('jezykSzkolenia')}</span></td>
            <td colspan="3">
              hiszpański [${L2 === 'es' ? 'X' : ' '}] &nbsp;&nbsp;
              ukraiński [${L2 === 'ua' ? 'X' : ' '}] &nbsp;&nbsp;
              angielski [${L2 === 'en' ? 'X' : ' '}]
            </td></tr>
        <tr><td><span class="lbl">${t('programSzkolenia')}</span><br>
              <span class="tlum" style="font-size:7pt;">${t('programOpis')}</span></td>
            <td colspan="3">${programRows}</td></tr>
        <tr><td><span class="lbl">${t('uwagiZgloszone')}</span></td>
            <td colspan="3" style="height:15mm;">${szkEsc(szkUsunZnaczniki(s.uwagi || ''))}</td></tr>
        <tr><td><span class="lbl">${t('weryfikacja')}</span></td>
            <td colspan="3" style="height:15mm;"></td></tr>
      </table>

      <div class="podpisy">
        <div class="podpis">${t('podpisSzkolacego')}<br><span class="tlum">${t('czytelnie')}</span></div>
        <div class="podpis">${t('podpisTlumacza')}<br><span class="tlum">${t('czytelnie')}</span></div>
      </div>

      <div class="podpisy" style="margin-top:4mm;">
        <div class="podpis">${t('podpisWeryfikujacego')}<br><span class="tlum">${t('czytelnie')}</span></div>
      </div>
    </div>`;
  };

  // Strona 3 — lista obecności (min. 25 wierszy jak we wzorze)
  const t = (k) => szkEsc(szkT('pl', k));
  const uczestnicy = s.uczestnicy || [];
  let wiersze = '';
  const ile = Math.max(25, uczestnicy.length);
  for (let i = 0; i < ile; i++) {
    wiersze += `<tr>
      <td style="width:8%;text-align:center;">${i + 1}</td>
      <td style="width:52%;">${szkEsc(szkUsunZnaczniki(uczestnicy[i] || ''))}</td>
      <td style="width:20%;"></td>
      <td style="width:20%;"></td>
    </tr>`;
  }

  const stronaLista = `
    <div class="doc">
      <div class="naglowek-dok">
        <div style="width:22%;display:flex;align-items:center;justify-content:center;padding:1mm;"><img src="${szkState.logoDataUri}" style="height:24mm;max-width:100%;display:block;" alt="perla"></div>
        <div style="width:38%;"><strong>${szkEsc(szkState.dokMetaProtokol.nazwa)}</strong><br>${t('stron')}: 3/3<br>Nr dok.: ${szkEsc(szkState.dokMetaProtokol.nrDok)}<br>Opracował: ${szkEsc(szkState.dokMetaProtokol.opracowal)}</div>
        <div style="width:25%;">Nr wydania: ${szkEsc(szkState.dokMetaProtokol.nrWydania)}<br>Data wyd.: ${szkEsc(szkState.dokMetaProtokol.dataWydania)}<br>Zatwierdził:<br>${szkEsc(szkState.dokMetaProtokol.zatwierdzil)}</div>
        <div style="width:15%;text-align:center;"><strong>${szkEsc(szkState.dokMetaProtokol.symbol)}</strong><br>${szkEsc(szkState.dokMetaProtokol.symbolOpis)}</div>
      </div>
      <div style="font-weight:bold;margin-bottom:3mm;">${t('listaObecnosci')}</div>
      <table>
        <thead><tr class="naglowek-tabeli">
          <td style="text-align:center;">${t('lp')}</td>
          <td>${t('uczestnik')}<br><span style="font-weight:normal;font-size:7pt;">${t('czytelnie')}</span></td>
          <td>${t('data')}</td>
          <td>${t('podpisUczestnika')}</td>
        </tr></thead>
        <tbody>${wiersze}</tbody>
      </table>
    </div>`;

  return strona('pl', 1, s.temat, s.programPl)
       + strona(L2, 2, s.tematTlum || s.temat, s.programTlum || s.programPl)
       + stronaLista;
}

function drukujSzkolenie(id) {
  const s = szkState.lista.find(x => x.id === id);
  if (!s) { showToast('Nie znaleziono karty'); return; }
  const tresc = s.typ === 'indywidualne' ? budujKarteIndywidualna(s) : budujProtokolGrupowy(s);
  const tytul = s.typ === 'indywidualne'
    ? `Karta szkolenia — ${s.pracownikImieNazwisko}`
    : `Protokół szkolenia — ${s.temat}`;

  const w = window.open('', '_blank');
  if (!w) { showToast('Zezwól na otwieranie okien, aby wydrukować'); return; }
  w.document.write(`<!DOCTYPE html><html lang="pl"><head><meta charset="utf-8">
    <title>${szkEsc(tytul)}</title><style>${SZK_PRINT_CSS}</style></head>
    <body>${tresc}</body></html>`);
  w.document.close();
  setTimeout(() => { try { w.focus(); w.print(); } catch (e) {} }, 400);
}

// ===== INTERFEJS SŁOWNIKA =====
const SZK_JEZYKI = [
  { kod: 'ua', flaga: '🇺🇦', nazwa: 'ukraiński' },
  { kod: 'en', flaga: '🇬🇧', nazwa: 'angielski' },
  { kod: 'es', flaga: '🇪🇸', nazwa: 'hiszpański' }
];

let szkSlownikEditKey = null;

function renderSzkSlownik() {
  const wrap = document.getElementById('szkSlownikLista');
  if (!wrap) return;
  const fraza = (document.getElementById('szkSlownikSzukaj').value || '').toLowerCase().trim();

  let lista = szkState.slownik.slice();
  if (fraza) {
    lista = lista.filter(p =>
      (p.pl || '').toLowerCase().includes(fraza) ||
      (p.ua || '').toLowerCase().includes(fraza) ||
      (p.en || '').toLowerCase().includes(fraza) ||
      (p.es || '').toLowerCase().includes(fraza)
    );
  }
  lista.sort((a, b) => (a.pl || '').localeCompare(b.pl || '', 'pl'));

  const pods = document.getElementById('szkSlownikPodsumowanie');
  if (pods) {
    pods.textContent = szkState.slownik.length
      ? `Pozycji w słowniku: ${szkState.slownik.length}${fraza ? ` · pasujących: ${lista.length}` : ''}`
      : 'Słownik jest pusty — zapełni się sam przy zapisywaniu kart.';
  }

  if (!lista.length) {
    wrap.innerHTML = fraza
      ? '<div class="hint">— brak pasujących pozycji —</div>'
      : '<div class="hint">— brak pozycji —</div>';
    return;
  }

  wrap.innerHTML = lista.map(p => {
    const tlum = SZK_JEZYKI
      .map(j => p[j.kod] ? `${j.flaga} ${szkEsc(p[j.kod])}` : `${j.flaga} <span style="color:var(--text-dim);">—</span>`)
      .join('<br>');
    return `
      <div class="storage-row" style="margin-bottom:6px;flex-direction:column;align-items:flex-start;gap:3px;">
        <strong style="width:100%;">${szkEsc(p.pl)}</strong>
        <span style="font-size:12px;line-height:1.5;">${tlum}</span>
        <span>
          <button class="btn secondary" data-slow-edit="${szkEsc(szkKluczFrazy(p.pl))}" style="margin-right:4px;">Edytuj</button>
          <button class="btn danger" data-slow-del="${szkEsc(szkKluczFrazy(p.pl))}">Usuń</button>
        </span>
      </div>`;
  }).join('');

  wrap.querySelectorAll('[data-slow-edit]').forEach(btn => {
    btn.addEventListener('click', () => {
      const poz = szkState.slownik.find(p => szkKluczFrazy(p.pl) === btn.dataset.slowEdit);
      if (!poz) return;
      szkSlownikEditKey = btn.dataset.slowEdit;
      document.getElementById('szkSlownikPl').value = poz.pl || '';
      document.getElementById('szkSlownikUa').value = poz.ua || '';
      document.getElementById('szkSlownikEn').value = poz.en || '';
      document.getElementById('szkSlownikEs').value = poz.es || '';
      document.getElementById('szkSlownikFormTytul').textContent = 'Edytuj pozycję';
      document.getElementById('szkSlownikCancelBtn').style.display = 'inline-block';
      document.getElementById('szkSlownikPl').scrollIntoView({ behavior: 'smooth', block: 'center' });
    });
  });

  wrap.querySelectorAll('[data-slow-del]').forEach(btn => {
    btn.addEventListener('click', async () => {
      const poz = szkState.slownik.find(p => szkKluczFrazy(p.pl) === btn.dataset.slowDel);
      if (!poz) return;
      if (!confirm(`Usunąć "${poz.pl}" ze słownika?`)) return;
      szkState.slownik = szkState.slownik.filter(p => szkKluczFrazy(p.pl) !== btn.dataset.slowDel);
      await szkSaveSlownik();
      renderSzkSlownik();
      showToast('Pozycja usunięta');
    });
  });
}

function szkResetSlownikForm() {
  szkSlownikEditKey = null;
  ['szkSlownikPl', 'szkSlownikUa', 'szkSlownikEn', 'szkSlownikEs'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  document.getElementById('szkSlownikFormTytul').textContent = 'Dodaj pozycję';
  document.getElementById('szkSlownikCancelBtn').style.display = 'none';
}

document.getElementById('szkOpenSlownikBtn') && document.getElementById('szkOpenSlownikBtn').addEventListener('click', async () => {
  await szkLoadSlownik();
  szkResetSlownikForm();
  document.getElementById('szkSlownikSzukaj').value = '';
  renderSzkSlownik();
  document.getElementById('szkSlownikModalOverlay').classList.add('active');
});

