// ===== DANE DOKUMENTÓW (nagłówek na wydruku) =====
function szkWypelnijFormularzDokMeta() {
  const p = szkState.dokMetaProtokol, k = szkState.dokMetaKarta;
  document.getElementById('szkDokMetaP_nazwa').value = p.nazwa;
  document.getElementById('szkDokMetaP_nrDok').value = p.nrDok;
  document.getElementById('szkDokMetaP_opracowal').value = p.opracowal;
  document.getElementById('szkDokMetaP_zatwierdzil').value = p.zatwierdzil;
  document.getElementById('szkDokMetaP_nrWydania').value = p.nrWydania;
  document.getElementById('szkDokMetaP_dataWydania').value = p.dataWydania;
  document.getElementById('szkDokMetaP_symbol').value = p.symbol;
  document.getElementById('szkDokMetaP_symbolOpis').value = p.symbolOpis;

  document.getElementById('szkDokMetaK_nazwa').value = k.nazwa;
  document.getElementById('szkDokMetaK_nrDok').value = k.nrDok;
  document.getElementById('szkDokMetaK_opracowal').value = k.opracowal;
  document.getElementById('szkDokMetaK_zatwierdzil').value = k.zatwierdzil;
  document.getElementById('szkDokMetaK_nrWydania').value = k.nrWydania;
  document.getElementById('szkDokMetaK_dataWydania').value = k.dataWydania;
  document.getElementById('szkDokMetaK_symbol').value = k.symbol;
  document.getElementById('szkDokMetaK_symbolOpis').value = k.symbolOpis;

  document.getElementById('szkLogoPreview').src = szkState.logoDataUri;
  szkPendingLogoDataUri = null; // nic jeszcze nie wybrano w tej sesji edycji
}

// Logo — jedno wspólne dla obu typów dokumentów (tak jak jest dziś na wzorach).
// Wgrywane jako plik, trzymane "w oczekiwaniu" do kliknięcia Zapisz — dopiero
// wtedy trwale zapisywane, tak jak reszta pól w tym formularzu.
let szkPendingLogoDataUri = null;

document.getElementById('szkLogoFile') && document.getElementById('szkLogoFile').addEventListener('change', (e) => {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    szkPendingLogoDataUri = reader.result;
    document.getElementById('szkLogoPreview').src = szkPendingLogoDataUri;
  };
  reader.readAsDataURL(file);
});

document.getElementById('szkLogoResetBtn') && document.getElementById('szkLogoResetBtn').addEventListener('click', () => {
  szkPendingLogoDataUri = SZK_LOGO_DEFAULT;
  document.getElementById('szkLogoPreview').src = SZK_LOGO_DEFAULT;
  document.getElementById('szkLogoFile').value = '';
});

document.getElementById('szkOpenDokMetaBtn') && document.getElementById('szkOpenDokMetaBtn').addEventListener('click', async () => {
  await szkLoadDokMeta();
  szkWypelnijFormularzDokMeta();
  document.getElementById('szkDokMetaModalOverlay').classList.add('active');
});

// Ten sam modal, dostępny też BEZ WYCHODZENIA z formularza wypełnianej karty
// (zagnieżdżony nad nim, z-index:110) — nie trzeba już przerywać wpisywania
// danych szkolenia, żeby poprawić logo albo nagłówek.
