document.getElementById('szkDokMetaSaveBtn') && document.getElementById('szkDokMetaSaveBtn').addEventListener('click', async () => {
  const pole = (id) => document.getElementById(id).value.trim();
  szkState.dokMetaProtokol = {
    nazwa: pole('szkDokMetaP_nazwa'), nrDok: pole('szkDokMetaP_nrDok'), opracowal: pole('szkDokMetaP_opracowal'),
    zatwierdzil: pole('szkDokMetaP_zatwierdzil'), nrWydania: pole('szkDokMetaP_nrWydania'),
    dataWydania: pole('szkDokMetaP_dataWydania'), symbol: pole('szkDokMetaP_symbol'),
    symbolOpis: pole('szkDokMetaP_symbolOpis')
  };
  szkState.dokMetaKarta = {
    nazwa: pole('szkDokMetaK_nazwa'), nrDok: pole('szkDokMetaK_nrDok'), opracowal: pole('szkDokMetaK_opracowal'),
    zatwierdzil: pole('szkDokMetaK_zatwierdzil'), nrWydania: pole('szkDokMetaK_nrWydania'),
    dataWydania: pole('szkDokMetaK_dataWydania'), symbol: pole('szkDokMetaK_symbol'),
    symbolOpis: pole('szkDokMetaK_symbolOpis')
  };
  await DB.setSetting('szkDokMetaProtokol', szkState.dokMetaProtokol);
  await DB.setSetting('szkDokMetaKarta', szkState.dokMetaKarta);

  if (szkPendingLogoDataUri) {
    if (szkPendingLogoDataUri === SZK_LOGO_DEFAULT) {
      await DB.setSetting('szkLogoCustom', null);
    } else {
      await DB.setSetting('szkLogoCustom', szkPendingLogoDataUri);
    }
    szkState.logoDataUri = szkPendingLogoDataUri;
    szkPendingLogoDataUri = null;
  }

  document.getElementById('szkDokMetaModalOverlay').classList.remove('active');
  showToast('Dane dokumentów zapisane');
});
document.getElementById('szkSlownikSzukaj') && document.getElementById('szkSlownikSzukaj').addEventListener('input', renderSzkSlownik);
document.getElementById('szkSlownikCancelBtn') && document.getElementById('szkSlownikCancelBtn').addEventListener('click', szkResetSlownikForm);

document.getElementById('szkSlownikSaveBtn') && document.getElementById('szkSlownikSaveBtn').addEventListener('click', async () => {
  const pl = document.getElementById('szkSlownikPl').value.trim();
  if (!pl) { showToast('Podaj frazę po polsku'); return; }
  const ua = document.getElementById('szkSlownikUa').value.trim();
  const en = document.getElementById('szkSlownikEn').value.trim();
  const es = document.getElementById('szkSlownikEs').value.trim();
  if (!ua && !en && !es) { showToast('Podaj przynajmniej jedno tłumaczenie'); return; }

  const klucz = szkKluczFrazy(pl);
  const kolizja = szkState.slownik.find(p =>
    szkKluczFrazy(p.pl) === klucz && szkKluczFrazy(p.pl) !== szkSlownikEditKey
  );
  if (kolizja && !szkSlownikEditKey) {
    if (!confirm(`"${kolizja.pl}" jest już w słowniku. Nadpisać jej tłumaczenia?`)) return;
    kolizja.pl = pl; kolizja.ua = ua; kolizja.en = en; kolizja.es = es;
  } else if (szkSlownikEditKey) {
    const poz = szkState.slownik.find(p => szkKluczFrazy(p.pl) === szkSlownikEditKey);
    if (poz) { poz.pl = pl; poz.ua = ua; poz.en = en; poz.es = es; }
  } else {
    szkState.slownik.push({ pl, ua, en, es });
  }

  await szkSaveSlownik();
  szkResetSlownikForm();
  renderSzkSlownik();
  showToast('Zapisano w słowniku');
});

// ===== UZUPEŁNIANIE TŁUMACZEŃ ZE SŁOWNIKA =====
document.querySelectorAll('[data-szk-uzupelnij]').forEach(btn => {
  btn.addEventListener('click', () => {
    const [idPl, idTlum] = btn.dataset.szkUzupelnij.split('|');
    const lang = document.getElementById('szkJezykDodatkowy').value || 'ua';
    const polePl = document.getElementById(idPl);
    const poleTlum = document.getElementById(idTlum);
    if (!polePl || !poleTlum) return;

    if (!polePl.value.trim()) { showToast('Najpierw wpisz treść po polsku'); return; }

    const wynik = szkUzupelnijListe(polePl.value, poleTlum.value, lang);
    poleTlum.value = wynik.tekst;

    if (wynik.uzupelnione && wynik.brakujace) {
      showToast(`Uzupełniono: ${wynik.uzupelnione} · brak w słowniku: ${wynik.brakujace}`);
    } else if (wynik.uzupelnione) {
      showToast(`Uzupełniono wszystkie: ${wynik.uzupelnione}`);
    } else if (wynik.brakujace) {
      showToast('Brak tych pozycji w słowniku — wpisz tłumaczenia ręcznie');
    } else {
      showToast('Wszystkie pozycje mają już tłumaczenia');
    }
  });
});

// ===== PODPOWIEDZI PRZY PISANIU (pola jednoliniowe) =====
// Po wpisaniu frazy, która jest w słowniku, tłumaczenie wstawia się samo
// — o ile pole tłumaczenia jest jeszcze puste.
function szkPodepnijPodpowiedz(idPl, idTlum) {
  const polePl = document.getElementById(idPl);
  const poleTlum = document.getElementById(idTlum);
  if (!polePl || !poleTlum) return;

  polePl.addEventListener('blur', () => {
    if (poleTlum.value.trim()) return;              // nie nadpisujemy tego, co wpisał użytkownik
    if (szkCalaLiniaBezTlumaczenia(polePl.value)) return;  // oznaczone gwiazdkami
    const lang = document.getElementById('szkJezykDodatkowy').value || 'ua';
    const znalezione = szkZnajdzTlumaczenie(polePl.value, lang);
    if (znalezione) {
      poleTlum.value = znalezione;
      showToast('Tłumaczenie ze słownika');
    }
  });
}

szkPodepnijPodpowiedz('szkObszar', 'szkObszarTlum');
szkPodepnijPodpowiedz('szkStanowisko', 'szkStanowiskoTlum');
szkPodepnijPodpowiedz('szkTemat', 'szkTematTlum');

// ===== SEKCJA II: OBSZARY (podgrupy z osobnymi tabelami) =====
// Każdy obszar to { nazwa, pozycjePl, pozycjeTlum } — na wydruku osobna tabela
// z własnym nagłówkiem kolumn i własnymi podpisami.
// Karty zapisane przed tą zmianą mają płaskie matrycaPl/matrycaTlum — wtedy
// drukujemy je po staremu, jako jedną tabelę bez podziału.

let szkObszaryRobocze = [];

function szkNowyObszar(nazwa, pozycjePl, pozycjeTlum) {
  return {
    nazwa: nazwa || '',
    pozycjePl: pozycjePl || '',
    pozycjeTlum: pozycjeTlum || ''
  };
}

function renderSzkObszary() {
  const wrap = document.getElementById('szkObszaryLista');
  if (!wrap) return;

  if (!szkObszaryRobocze.length) {
    wrap.innerHTML = '<div class="hint" style="padding:10px;background:var(--bg2);border-radius:8px;">Brak obszarów — kliknij „Dodaj obszar", żeby zacząć.</div>';
    return;
  }

  wrap.innerHTML = szkObszaryRobocze.map((o, i) => `
    <div style="border:1px solid var(--border);border-radius:9px;padding:10px;margin-bottom:10px;background:var(--bg2);">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">
        <span style="font-weight:800;color:var(--accent2);font-size:12px;">OBSZAR ${i + 1}</span>
        <span style="margin-left:auto;">
          ${i > 0 ? `<button class="btn secondary" data-obsz-gora="${i}" style="padding:2px 8px;font-size:12px;">↑</button>` : ''}
          ${i < szkObszaryRobocze.length - 1 ? `<button class="btn secondary" data-obsz-dol="${i}" style="padding:2px 8px;font-size:12px;">↓</button>` : ''}
          <button class="btn danger" data-obsz-usun="${i}" style="padding:2px 8px;font-size:12px;">Usuń</button>
        </span>
      </div>
      <div class="field">
        <label>Nazwa obszaru</label>
        <input type="text" data-obsz-nazwa="${i}" value="${szkEsc(o.nazwa)}" placeholder="np. Kuchnia Antipasti">
      </div>
      <div class="field">
        <label>Pozycje (PL) — jedna w wierszu</label>
        <textarea data-obsz-pl="${i}" rows="4" placeholder="Podłoga&#10;Kutry">${szkEsc(o.pozycjePl)}</textarea>
      </div>
      <div class="field">
        <label>Tłumaczenie (ta sama liczba wierszy)</label>
        <textarea data-obsz-tlum="${i}" rows="4" placeholder="Підлога&#10;Кутери">${szkEsc(o.pozycjeTlum)}</textarea>
        <button class="btn secondary full-width" data-obsz-uzupelnij="${i}" style="margin-top:6px;font-size:12.5px;">🔎 Uzupełnij tłumaczenia ze słownika</button>
      </div>
    </div>
  `).join('');

  // Zapisywanie zmian w polach
  wrap.querySelectorAll('[data-obsz-nazwa]').forEach(el => {
    el.addEventListener('input', () => { szkObszaryRobocze[+el.dataset.obszNazwa].nazwa = el.value; });
  });
  wrap.querySelectorAll('[data-obsz-pl]').forEach(el => {
    el.addEventListener('input', () => { szkObszaryRobocze[+el.dataset.obszPl].pozycjePl = el.value; });
  });
  wrap.querySelectorAll('[data-obsz-tlum]').forEach(el => {
    el.addEventListener('input', () => { szkObszaryRobocze[+el.dataset.obszTlum].pozycjeTlum = el.value; });
  });

  // Kolejność i usuwanie
  wrap.querySelectorAll('[data-obsz-gora]').forEach(btn => {
    btn.addEventListener('click', () => {
      const i = +btn.dataset.obszGora;
      [szkObszaryRobocze[i - 1], szkObszaryRobocze[i]] = [szkObszaryRobocze[i], szkObszaryRobocze[i - 1]];
      renderSzkObszary();
    });
  });
  wrap.querySelectorAll('[data-obsz-dol]').forEach(btn => {
    btn.addEventListener('click', () => {
      const i = +btn.dataset.obszDol;
      [szkObszaryRobocze[i], szkObszaryRobocze[i + 1]] = [szkObszaryRobocze[i + 1], szkObszaryRobocze[i]];
      renderSzkObszary();
    });
  });
  wrap.querySelectorAll('[data-obsz-usun]').forEach(btn => {
    btn.addEventListener('click', () => {
      const i = +btn.dataset.obszUsun;
      const o = szkObszaryRobocze[i];
      const maTresc = (o.nazwa || '').trim() || (o.pozycjePl || '').trim();
      if (maTresc && !confirm(`Usunąć obszar "${o.nazwa || '(bez nazwy)'}" wraz z pozycjami?`)) return;
      szkObszaryRobocze.splice(i, 1);
      renderSzkObszary();
    });
  });

  // Uzupełnianie ze słownika w obrębie obszaru
  wrap.querySelectorAll('[data-obsz-uzupelnij]').forEach(btn => {
    btn.addEventListener('click', () => {
      const i = +btn.dataset.obszUzupelnij;
      const o = szkObszaryRobocze[i];
      if (!(o.pozycjePl || '').trim()) { showToast('Najpierw wpisz pozycje po polsku'); return; }
      const lang = document.getElementById('szkJezykDodatkowy').value || 'ua';
      const wynik = szkUzupelnijListe(o.pozycjePl, o.pozycjeTlum, lang);
      o.pozycjeTlum = wynik.tekst;
      renderSzkObszary();
      if (wynik.uzupelnione && wynik.brakujace) {
        showToast(`Uzupełniono: ${wynik.uzupelnione} · brak: ${wynik.brakujace}`);
      } else if (wynik.uzupelnione) {
        showToast(`Uzupełniono wszystkie: ${wynik.uzupelnione}`);
      } else {
        showToast('Brak tych pozycji w słowniku');
      }
    });
  });
}

document.getElementById('szkDodajObszarBtn') && document.getElementById('szkDodajObszarBtn').addEventListener('click', () => {
  szkObszaryRobocze.push(szkNowyObszar());
  renderSzkObszary();
  // Przewiń do nowego obszaru i ustaw kursor w nazwie
  setTimeout(() => {
    const pola = document.querySelectorAll('[data-obsz-nazwa]');
    const ostatnie = pola[pola.length - 1];
    if (ostatnie) { ostatnie.scrollIntoView({ behavior: 'smooth', block: 'center' }); ostatnie.focus(); }
  }, 50);
});

